begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000081'),('00000000-0000-4000-8000-000000000082');
insert into public.surf_spots(id,user_id,name) values ('10000000-0000-4000-8000-000000000081','00000000-0000-4000-8000-000000000081','Equipment test');
insert into public.surf_sessions(id,user_id,spot_id,started_at,ended_at,board_name) values ('20000000-0000-4000-8000-000000000081','00000000-0000-4000-8000-000000000081','10000000-0000-4000-8000-000000000081','2026-11-22T00:00:00Z','2026-11-22T01:00:00Z','  Old Board  ');
insert into public.surf_session_conditions(session_id,wetsuit) values ('20000000-0000-4000-8000-000000000081',' 4/3mm ');
insert into public.user_equipment(user_id,equipment_type,name) values ('00000000-0000-4000-8000-000000000082','surfboard','Private B');
select ok((select relrowsecurity from pg_class where oid='public.user_equipment'::regclass),'Equipment RLS enabled');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000081',true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000081","role":"authenticated"}',true);
select is((select count(*) from public.user_equipment),0::bigint,'Cannot read another user equipment');
select is((select count(*) from public.register_my_equipment(' Old  Board ','4/3mm')),2::bigint,'Register both names atomically');
select is((select name from public.user_equipment where equipment_type='surfboard'),'Old Board','Whitespace normalized');
select count(*) from public.register_my_equipment('old board',' 4/3mm ');
select count(*) from public.register_my_equipment('Old'||chr(160)||'Board',null);
select is((select count(*) from public.user_equipment),2::bigint,'Case/whitespace retry creates no duplicates');
select throws_ok($$insert into public.user_equipment(user_id,equipment_type,name) values (auth.uid(),'surfboard','OLD BOARD')$$,'23505',null,'Database uniqueness protects concurrent inserts');
update public.user_equipment set name='Renamed Board' where equipment_type='surfboard';
select is((select board_name from public.surf_sessions where id='20000000-0000-4000-8000-000000000081'),'  Old Board  ','Rename never rewrites journal snapshot');
update public.user_equipment set is_active=false where equipment_type='wetsuit';
select is((select wetsuit from public.surf_session_conditions where session_id='20000000-0000-4000-8000-000000000081'),' 4/3mm ','Archive never rewrites suit snapshot');
select is((select count(*) from public.user_equipment where is_active),1::bigint,'Archived item hidden from active list');
select count(*) from public.register_my_equipment(null,'4/3mm');
select is((select count(*) from public.user_equipment where is_active),2::bigint,'Explicit re-registration reactivates existing item');
select throws_ok($$select * from public.register_my_equipment('Atomic new board',repeat('x',201))$$,'23514',null,'Invalid second name rolls back pair');
select is((select count(*) from public.user_equipment where name='Atomic new board'),0::bigint,'No partial registration after failure');
select throws_ok($$update public.user_equipment set user_id='00000000-0000-4000-8000-000000000082'$$,'42501',null,'Cannot transfer ownership');
select throws_ok($$insert into public.user_equipment(user_id,equipment_type,name) values ('00000000-0000-4000-8000-000000000082','wetsuit','Forbidden')$$,'42501',null,'Cannot create for B');
with changed as (update public.user_equipment set name='Forbidden' where user_id='00000000-0000-4000-8000-000000000082' returning *) select is(count(*),0::bigint,'Cannot rename B equipment') from changed;
with changed as (update public.user_equipment set is_active=false where user_id='00000000-0000-4000-8000-000000000082' returning *) select is(count(*),0::bigint,'Cannot archive B equipment') from changed;
select throws_ok($$delete from public.user_equipment$$,'42501',null,'Hard deletion is not granted');
select throws_ok($$insert into public.user_equipment(user_id,equipment_type,name) values (auth.uid(),'other','Test')$$,'23514',null,'Invalid type rejected');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok($$select * from public.user_equipment$$,'42501',null,'Anonymous read denied');
select throws_ok($$select * from public.register_my_equipment('x','y')$$,'42501',null,'Anonymous registration denied');
select throws_ok($$update public.user_equipment set is_active=false$$,'42501',null,'Anonymous update denied');
select throws_ok($$insert into public.user_equipment(user_id,equipment_type,name) values ('00000000-0000-4000-8000-000000000081','surfboard','x')$$,'42501',null,'Anonymous insert denied');
reset role;
select * from finish();
rollback;
